package com.bank.report;

import java.util.Arrays;

public class ReportBuilder {

    // parallelSetAll: fill each fee purely from its index (independent work).
    public double[] buildFeeSchedule(int tiers) {
        double[] fees = new double[tiers];
        Arrays.parallelSetAll(fees, i -> 10.0 + i * 0.5);   // tier i fee
        return fees;
    }

    // parallelSort: sort large transaction amounts ascending.
    public void sortAmounts(double[] amounts) {
        Arrays.parallelSort(amounts);
    }

    // parallelPrefix: running cumulative total down the array.
    public double[] runningTotal(double[] amounts) {
        double[] copy = Arrays.copyOf(amounts, amounts.length);
        Arrays.parallelPrefix(copy, Double::sum);           // prefix scan
        return copy;
    }
}
