package com.bank.report;

import java.util.Arrays;
import java.util.Random;
import java.util.concurrent.ForkJoinPool;
import java.util.logging.Logger;

public class ParallelArraysDemo {
    private static final Logger log = Logger.getLogger(ParallelArraysDemo.class.getName());

    public static void main(String[] args) {
        int n = 5_000_000;
        double[] amounts = new double[n];
        Random rnd = new Random(42);
        // parallelSetAll with index-derived randomness
        Arrays.parallelSetAll(amounts, i -> Math.abs((i * 2654435761L) % 100000) / 100.0);

        ReportBuilder builder = new ReportBuilder();

        double[] parCopy = Arrays.copyOf(amounts, n);
        long t0 = System.nanoTime();
        builder.sortAmounts(parCopy);                 // parallelSort
        long parMs = (System.nanoTime() - t0) / 1_000_000;

        double[] seqCopy = Arrays.copyOf(amounts, n);
        long t1 = System.nanoTime();
        Arrays.sort(seqCopy);                         // sequential baseline
        long seqMs = (System.nanoTime() - t1) / 1_000_000;

        double[] fees = builder.buildFeeSchedule(5);
        double[] running = builder.runningTotal(new double[]{100, 200, 300, 400});

        log.info(() -> "parallelSort " + parMs + "ms vs sequential " + seqMs + "ms");
        log.info(() -> "sorted ok=" + Arrays.equals(parCopy, seqCopy));
        log.info(() -> "fee schedule=" + Arrays.toString(fees));
        log.info(() -> "running total=" + Arrays.toString(running));
        log.info(() -> "common pool parallelism=" + ForkJoinPool.commonPool().getParallelism());
    }
}
