package com.bank.report;

import org.junit.jupiter.api.Test;
import java.util.Arrays;
import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

class ReportBuilderTest {
    @Test
    void parallelOpsProduceCorrectResults() {
        ReportBuilder b = new ReportBuilder();

        double[] amounts = {300, 100, 200};
        b.sortAmounts(amounts);
        assertArrayEquals(new double[]{100, 200, 300}, amounts, 0.0001);

        double[] running = b.runningTotal(new double[]{100, 200, 300, 400});
        assertArrayEquals(new double[]{100, 300, 600, 1000}, running, 0.0001);

        double[] fees = b.buildFeeSchedule(3);
        assertTrue(fees[0] == 10.0 && fees[1] == 10.5 && fees[2] == 11.0);
    }
}
